const now = new Date().toISOString();

return items.map(item => {
  return {
    json: {
      row_number: item.json.row_number,
      lock_key: item.json.lock_key,
      status: 'cancelled',
      finished_at: now,
      cancel_reason: 'admin_stop_all_flow'
    }
  };
});

const body = $('Webhook').first().json.body || {};
const chatId = String(body.chat_id || body.message?.chat?.id || '').replace(/^=/, '');

const now = Date.now();

const rows = items
  .map(item => item.json || {})
  .filter(row => {
    const status = String(row.status || '').trim().toLowerCase();
    const expiresAt = Date.parse(String(row.expires_at || '').trim());

    return (
      status === 'active' &&
      Number.isFinite(expiresAt) &&
      expiresAt > now
    );
  });

let text = '';

if (!rows.length) {
  text = 'Активных задач нет.';
} else {
  text = 'Активные задачи:\n\n';

  rows.forEach((row, index) => {
    text += `${index + 1}. lock_key: ${row.lock_key || '-'}\n`;
    text += `   task_id: ${row.task_id || '-'}\n`;
    text += `   created_at: ${row.created_at || '-'}\n`;
    text += `   expires_at: ${row.expires_at || '-'}\n`;
    text += `   status: ${row.status || '-'}\n\n`;
  });
}

return [{
  json: {
    chat_id: chatId,
    telegram_text: text,
    admin_command: 'locks'
  }
}];

const body = $('Webhook').first().json.body || {};
const chatId = String(body.chat_id || body.message?.chat?.id || '').replace(/^=/, '');

function getNodeItems(nodeName) {
  try {
    return $(nodeName).all();
  } catch (e) {
    return [{
      json: {
        __health_error: String(e.message || e)
      }
    }];
  }
}

function checkSheet(nodeName) {
  const nodeItems = getNodeItems(nodeName);

  if (!Array.isArray(nodeItems) || nodeItems.length === 0) {
    return {
      ok: false,
      message: 'нет output items'
    };
  }

  const first = nodeItems[0]?.json || {};

  if (first.__health_error) {
    return {
      ok: false,
      message: first.__health_error
    };
  }

  if (first.error) {
    return {
      ok: false,
      message: String(first.error)
    };
  }

  if (first.message && /error|ошибка|bad request/i.test(String(first.message))) {
    return {
      ok: false,
      message: String(first.message)
    };
  }

  return {
    ok: true,
    message: `лист читается, items: ${nodeItems.length}`
  };
}

const activeJobs = checkSheet('Health Check Active Jobs');
const memory = checkSheet('Health Check Memory');

const allOk = activeJobs.ok && memory.ok;

const text = [
  'Health Check — SEO Content Agent',
  '',
  `Google Sheets: ${allOk ? 'OK' : 'ERROR'}`,
  `seo_active_jobs: ${activeJobs.ok ? 'OK' : 'ERROR'} — ${activeJobs.message}`,
  `memory: ${memory.ok ? 'OK' : 'ERROR'} — ${memory.message}`,
  '',
  `Статус: ${allOk ? 'система доступна' : 'есть проблема с доступом к таблицам'}`
].join('\n');

return [{
  json: {
    chat_id: chatId,
    telegram_text: text,
    admin_command: 'health'
  }
}];
